import re
Uc=U-U.mean(0)
ok=torch.tensor([bool(re.fullmatch(r"[ A-Za-z]{3,}",tok.decode([t]))) for t in range(U.shape[0])])
def topc(v,n=15):
    s=(Uc@(v*normf)); s[~ok]=0
    i=torch.topk(s,n).indices; j=torch.topk(-s,n).indices
    return [tok.decode([t]) for t in i.tolist()],[tok.decode([t]) for t in j.tolist()]
